```c
#include <stdio.h>

struct Complex {
    float r, i;
};

int main() {
    struct Complex a, b, sum;

    printf("Enter real and imaginary part of 1st number: ");
    scanf("%f %f", &a.r, &a.i);

    printf("Enter real and imaginary part of 2nd number: ");
    scanf("%f %f", &b.r, &b.i);

    sum.r = a.r + b.r;
    sum.i = a.i + b.i;

    printf("Sum = %.1f + %.1fi\n", sum.r, sum.i);
    return 0;
}
```

### What’s simplified:
- Shorter variable names (`r`, `i` instead of `real`, `imag`).
